FILE: app/src/release.ts
```ts
import { getAnimationGroups, stopAnimation } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

function resolvePath(target: object, path: string): { owner: object; last: string } {
    const parts = path.split(".");
    let current: any = target;
    for (let i = 0; i < parts.length - 1; i++) {
        current = current[parts[i]];
        if (current == null) {
            throw new Error(`releaseProperty: path segment "${parts[i]}" not found (full path "${path}")`);
        }
    }
    return { owner: current, last: parts[parts.length - 1] };
}

export function releaseProperty(manager: AnimationManager, target: object, path: string): void {
    const { owner, last } = resolvePath(target, path);
    const groups = getAnimationGroups(manager);
    for (const group of groups) {
        const targeted = group.targetedAnimations;
        if (!targeted) continue;
        for (const ta of targeted) {
            if (ta.target === owner && ta.path === last) {
                stopAnimation(group);
                break;
            }
        }
    }
}
```

I wrote `src/release.ts` which resolves the dotted path to its owning object and final segment, then iterates every group on the manager checking `targetedAnimations` for a matching `(target, path)` pair and calls `stopAnimation` on any that match — stopping the whole group so it no longer writes the property (including under blending, per note 32). The only thing I wasn't fully sure of is whether `stopAnimation` is safe to call on a group that is already stopped; the notes imply it just resets `currentTime` and sets `_stopped`, so I assumed idempotency, but I couldn't verify the exact behavior on a double-stop.
